INSERT INTO phpbb_posts_text VALUES (39789, '03ec79560d', '', 'Nice! That\'s one evil lookin\' monster. I dig the flames.\r\n\r\nYeah, I\'d also like to know what Lego set you Aussies are getting those wheels from. All the Lego kits I\'ve seen had crappy wheels.\r\n\r\nEDIT: Nevermind, I got the gig on the wheels.\r\n\r\nYou can order them direct from Lego. 24 wheels in 3 sizes for 8 bucks.\r\nhttp://shop.lego.com/product.asp?p=10048&amp;t=5&amp;d=11&amp;c=5612D4DD-23E5-4FD3-8F54-C17254284D24');
