INSERT INTO phpbb_posts_text VALUES (771, '8435e7a4e6', 'new way to bling', 'you need these 3 things.\r\n\r\na dual color led(two prong/bidirectional)\r\n\r\nsoldering iron\r\n\r\nsteady hand\r\n\r\nsolder the led connectors to where the motor power wires attach to the motor terminals. fwd = green reverse = red\r\nthey dont light up while the motor is under load but once she winds up you get bling allover the place.\r\n\r\ni dont think it would work on a single cell bit.');
