INSERT INTO phpbb_posts_text VALUES (3739, 'af05f48d55', '', 'this car I just build is \'sick\'... just unbelieveable.\r\n\r\nyou still hear that clickin unbooster from the motor...\r\n\r\nbut when booster.. man.... it lurches forward.... just throws it self ...\r\n\r\nit\'s awesome starting in booster mode... it\'s maddening..\r\n\r\n-nox');
