INSERT INTO phpbb_posts_text VALUES (5864, '6e8070a58a', '', 'Crap, I gotta redo all the RPM tests.\r\n\r\nThe \'trick\' is to use an encoder wheel the SAME diameter as the driving wheels. Since I don\'t know the specific calculations to compensate for the encoder diameter (the bigger the diameter, the less RPMs will register), I\'ll have to settle for using a wheel as close to the regular wheels as possible.');
