INSERT INTO phpbb_posts_text VALUES (40230, 'ba0d7a9ffe', '', 'i used\r\n\r\n1: a piece of cardboard\r\n2: a soldering iron and some solder\r\n3: a few pieces of wire\r\n\r\ni soldered a wire to the positive end of one of the batteries. then i soldered to the negative on the third and ran a wire from the positive end of the third cell to the terminal in the battery compartment and put the cardboard inbetween the wires. the stock charger doesnt like to charge 3 cells however so get ready to rig that as well.');
