INSERT INTO phpbb_posts_text VALUES (9564, '5d3051113b', '', 'Kewl ez, that\'s an original design! Hows it working so far? Have you needed to change the e-tape on the neg. side of the battery yet, do to heat?\r\n\r\n-word');
