INSERT INTO phpbb_posts_text VALUES (10867, '1ca8f4ef90', '', 'My second and last entry.\r\n\r\n[img:1ca8f4ef90]http://plaza.ufl.edu/mpbiv/rc/bp1.jpg[/img:1ca8f4ef90]\r\n[img:1ca8f4ef90]http://plaza.ufl.edu/mpbiv/rc/bp3.jpg[/img:1ca8f4ef90]\r\n[img:1ca8f4ef90]http://plaza.ufl.edu/mpbiv/rc/bp2.jpg[/img:1ca8f4ef90]\r\n[img:1ca8f4ef90]http://plaza.ufl.edu/mpbiv/rc/bp4.jpg[/img:1ca8f4ef90]\r\n\r\n-MS Pro 27mhz chassis\r\n-2.6 motor with orange gears\r\n-Laymans internal dual cell 2.4V 40mah\r\n-Black painted wheels with full size fronts\r\n-Front lowered to offset larger wheels\r\n-Custom painted graphics\r\n-Custom driver and steering wheel\r\n-Simulated aluminum wing (painted)\r\n-Painted details and stuff.');
