INSERT INTO phpbb_posts_text VALUES (11177, '40483f5a32', '', 'sm2osley - that URL that you\'re using, it\'s a link to a page.\r\nput that link in your browsers address bar.\r\nyou\'ll see the picture you\'re wanting on that page.\r\nright click that picture.\r\nchoose "properties".\r\nin the middle of the properties window you\'ll see an area labeled "Address (URL):"\r\nto the right of that is the URL to that picture, this is the URL you want.\r\nyou must make sure you get the entire URL (most of the time they are long), either drag your cursor from the left of the "http:" and drag down and to the right until it stops and you have everything highlighted - or you can just click 3 times quick.\r\ncopy that URL, paste it in between the [img] [/img] tags.');
