INSERT INTO phpbb_posts_text VALUES (12392, 'a7bc53046b', 'Twisted Plastic Contest', 'Thanks to everyone for the suggestions\r\n\r\n[b:a7bc53046b]Contest Name:[/b:a7bc53046b] Twisted Plastic \r\n\r\n[b:a7bc53046b]Start Date:[/b:a7bc53046b] to be determined\r\n[b:a7bc53046b]End Date:[/b:a7bc53046b] 2 months from start date\r\n\r\n[b:a7bc53046b]Rules:[/b:a7bc53046b] Only micro r/c\'s (bit char-g, ms, zz, clones)\r\n\r\n[b:a7bc53046b]Judging Criteria:[/b:a7bc53046b] \r\n1) mod content \r\n2) paint job \r\n3) functionallity \r\n4) sex appeal \r\n5) sex appeal\r\n\r\n[b:a7bc53046b]Cars on the lot:[/b:a7bc53046b]\r\n- S2k\r\n- Gloria\r\n- Skyline (all 4 models)\r\n\r\n[b:a7bc53046b]Prizes:[/b:a7bc53046b]\r\n[color=darkred:a7bc53046b]Gloria:[/color:a7bc53046b]\r\n1st - Goes to the finals \r\n2nd - Perfection 3.8 (DT donate) \r\n3rd - Perfection 3.0 (DT donate) \r\n\r\n[color=darkblue:a7bc53046b]Skyline[/color:a7bc53046b]\r\n1st - Goes to the finals \r\n2nd - Perfection 3.8 (DT donate) \r\n3rd - Perfection 3.0 (DT donate)  \r\n\r\n[color=green:a7bc53046b]S2K:[/color:a7bc53046b]\r\n1st - Goes to the finals \r\n2nd - Perfection 3.8 (DT donate) \r\n3rd - Perfection 3.0 (DT donate)  \r\n\r\n[i:a7bc53046b]Finals:[/i:a7bc53046b]\r\n1st - 1 of every EX motor [estimated value $33.00]\r\n2nd - 1-MIT-02 [estimated value $20.00]\r\n3rd - 1-MIT-01 [estimated value $15.00]\r\n\r\n[b:a7bc53046b]going to keep updating this post as details are worked out and become more permanent[/b:a7bc53046b]');
