INSERT INTO phpbb_posts_text VALUES (13618, '7f67c8acbf', '', 'No on the optical (at least not easily)\r\n\r\nGotta have the guts of a ball mouse, the critical components are the LED emitter/decoder and encoder wheel (usually used to detect the vertical or horizontal mouse movement).');
