INSERT INTO phpbb_posts_text VALUES (13756, '07f7d9c5ca', 'The Naks are Here.....', 'Thanx EZ!\r\nGot my Nakamichi\'s in today!  Popped the batts in and gave it a whirl.\r\n\r\nController on comfy, don\'t like the Turbo switch  though I like the results.\r\n\r\nWith car in Turbo mode, it\'s fast, when turning it drops back down to normal and soon as you straighten the wheel, it kicks back into Turbo mode....neat! Turbo only works straight forward, not in reverse.\r\n\r\n[img:07f7d9c5ca]http://www.msnusers.com/_Secure/0QwCz*y4Uq6533ZVvigpaGA72eELhzj0Vz5DHKAVIHhScXK9GcbpVXpQZLBiAj0u1nzdKPG37EWBQxtwCJEFS0qwRGMn96enIO1EIfMHZ1Fk/Nakamichi.jpg?dc=4675427708418998961[/img:07f7d9c5ca]');
