INSERT INTO phpbb_posts_text VALUES (15288, '48fda9725c', '', 'can you steer but not go forward or reverse?\r\n\r\nstart simple, make sure you got the battery in correctly.\r\nmake sure you\'re getting proper contact on both battery posts.\r\nmake sure you\'re motor is getting proper contact on both the heatsink (clip) and the side contact post.\r\nmake sure all the wires are connected where they need to be.');
