INSERT INTO phpbb_posts_text VALUES (15302, 'ecdbfafa23', '', 'Nox, I\'m investigating some opto-sensor based circuits that count a value based on LED/Sensor pair.   When the beam is broken the count is registered.  This can be fed though a series of Divide-by-10 counters to get the sample rate down to the printer port limit (whatever that is).\r\n\r\nThis is still at the concept/functional stage, gotta do more research over the next few days......... :fool: \r\n\r\nph2t.');
