INSERT INTO phpbb_posts_text VALUES (15314, 'fdd59da9a7', '', 'Not much but only been in da game fur 3 months\r\n\r\nIn image : BITS\r\nLowerider truck/Acura NSX/Mazda RX-7/Honda S2000/Dodge Ram/Mitsibishi Lancer\r\n\r\n[img:fdd59da9a7]http://members.rogers.com/computermod/images/rc/extras%20and%20bits.JPG[/img:fdd59da9a7]\r\n\r\n\r\nEXTRA PARTS\r\n\r\n3x 150MAh batts 2x 60Mah Batts 1x 50 Mah Batts/ extra chassis and pcb/2x 2032 button cells for glow from below/green and blue LED\'s/5 sets rims/1 set phatty rear tires/2 sets slicks/2 set dirt/3.8/3.0/2.6/1.0 motors.');
