INSERT INTO phpbb_posts_text VALUES (16338, 'b50358490e', 'Easter Eggs', 'Post the Easter Eggs you\'ve found here, no matter if it\'s from a DVD, a program, etc.\r\nI\'ll start:\r\n\r\nDreamWeaver MX:\r\n- Click "Text &gt; CSS Styles &gt; New CSS Style..."\r\n- name it ".coilA" and define it in "This Document Only" (give it any styles)\r\n- Click "OK"\r\n- Under the "Design Palette" select "CSS Styles" and select ".coilA"\r\n- You should get a popup message "You have selected coil A. Detact the frequency?"\r\n- Click "Yes"\r\n\r\nVIOLA!\r\nyou should be taken to this weird site:\r\nhttp://www.alexchiu.com/');
