INSERT INTO phpbb_posts_text VALUES (18198, '2aae34930c', '', 'a dremel on a wheel well is a bit overkill. i have these snips that cut through plastic like nothing. all i do is carefully cut little pieces at a time.\r\n\r\n[img:2aae34930c]http://www.action-electronics.com/grc/xc170m.jpg[/img:2aae34930c]\r\n\r\nthey cost 5.49 and are really nice. \r\n\r\nhttp://www.action-electronics.com/cutters.htm');
