INSERT INTO phpbb_posts_text VALUES (19580, '4285c02c34', 'Cheap Motor holder', 'I finnaly found the solution to my motors rolling around my work area! \r\n\r\nMaterials:\r\nOne Microsnap motor package\r\nTape\r\nKnife\r\nscissors\r\n\r\n1 cut out the bubble portion of the packaging\r\n2 trace the edge of this on a part of the backing card\r\n3 cut out and tape to the back of the bubble\r\n4 mark holes ( i used a small nail )\r\n5 cut holes slightly smaller than diameter of the motor\r\n6 cut small slits from the holes \r\n7 adjust slits and hole till motor fits\r\n8 load your motors\r\n\r\nI only made holes for four motors but from the looks of it you could make it fit up to 10 motors :eek:');
