INSERT INTO phpbb_posts_text VALUES (19095, 'aea3ca619e', '', 'it stands for Greenwich Mean Time\r\n\r\nGMT remains the same all year around (no "spring forward" or "fall back")\r\n\r\nGMT is world time, makes correct time in every international time zone\r\nthough theoretically replaced by UTC (atomic time) it\'s still widely used.\r\n\r\nwhen you see the board is on GMT - 6:00, that means the board itself is in a timezone 6 hours behind GMT\r\n\r\nso if it were 10 pm GMT, the boards timezone is 4pm');
