INSERT INTO phpbb_posts_text VALUES (19558, '864091497b', '', 'I have to give you the same answer I\'ve given everyone else who\'s asked.\r\nNo - please do not use any content or images from bitPimps - it is legally copyrighted.\r\n\r\nI encourage you to start you own thing, but do just that - your own thing - do not use content or images from bitPimps please.\r\n\r\nIf other users grant you permission to use their content or images - that is another thing and doesn\'t concern me or bitPimps, but anything from the bitPimps does, so again I must re-itterate - please do not use any content or images from bitPimps - feel free to link to it, but you nor anyone else is allowed to publish it on their own site.');
