INSERT INTO phpbb_posts_text VALUES (38206, '6d16046346', '', 'Paint thinner will fog the plastic, and melt it if you\'re not careful. Soak the painted body in Castrol Super Clean for 30 minutes, scrub paint off with a toothbrush and wash with soapy water. CSC is safe on plastic and removes model paint beautifully.');
