INSERT INTO phpbb_posts_text VALUES (37951, '2224af4119', 'My italian Dreams(many Pics)!!!', 'Here are my lowered Murcie with a Special Chassi..it drive very good and its very low(i hope) :-)\r\n\r\nThis saws like not to much work..but it was hard work to dremel the Chassis and the Body...There are!\r\n\r\n-Pullbacks and Fets inside/Mosfet\r\n-Chassilowering\r\n-Bodylowering\r\n-new selfmate Headsink\r\n-lower Elektrik inside\r\n\r\n[img:2224af4119]http://land.heim.at/toskana/211863/Murcie0.jpg[/img:2224af4119]\r\n\r\n[img:2224af4119]http://land.heim.at/toskana/211863/Murcie2.jpg[/img:2224af4119]\r\n\r\n[img:2224af4119]http://land.heim.at/toskana/211863/Murcie1.jpg[/img:2224af4119]\r\n\r\ngreetings from Germany');
