INSERT INTO phpbb_posts_text VALUES (37830, '48451d3f98', '', 'Crazydave, \r\ndid u do the bypass mod yet? \r\n\r\nYou have to remove a resistor, then connect one side of the H-bridge directly to fully drive the gate on one of the 6401s. \r\n\r\nIt really opened up a whole new world of speed for my bit.. ;)\r\n\r\nRob');
