INSERT INTO phpbb_posts_text VALUES (22173, 'fd7a8049e0', '', '[b:fd7a8049e0]Entry:[/b:fd7a8049e0] #1\r\n[b:fd7a8049e0]Contestant:[/b:fd7a8049e0] Stoli\r\n[b:fd7a8049e0]Stats:[/b:fd7a8049e0]\r\n- Racing Skyline LXX CharG \r\n- 3.0 motor \r\n- Extra Soft Tires \r\n- Black Rims \r\n- Bigger Rear Axle For Drifting \r\n- Dropped Top \r\n- White Interor \r\n- Reloacated Antenna \r\n- Seating For Two Pimps\r\n[img:fd7a8049e0]http://bitpimps.lixlink.com/pages/phpGallery/albums/userpics/10001/contests/polish_turd/stoli_1_6.jpg[/img:fd7a8049e0]\r\n[img:fd7a8049e0]http://bitpimps.lixlink.com/pages/phpGallery/albums/userpics/10001/contests/polish_turd/stoli_1_8.jpg[/img:fd7a8049e0]');
