INSERT INTO phpbb_posts_text VALUES (23478, 'dcc3fa0966', 'New racetrack is born', 'Hi there,\r\n\r\nWe are building a racetrack for the microracers, you can follow our work on the following website. Maybe can you give me more information or sugestions by making this track.\r\n\r\nWe have also no name for the track, when you have one. let us know by sending an mail or leave a message in the guestbook. Thankssssssss\r\n\r\nBensuracer R&amp;R.\r\n\r\nhttp://members.lycos.nl/bensuracer/\r\n\r\n[img:dcc3fa0966]http://members.lycos.nl/bensuracer/pictures/DSC02714.JPG[/img:dcc3fa0966]');
