INSERT INTO phpbb_posts_text VALUES (23667, '18db8e7939', '', 'I\'m with Payaso, I just cut the steering knuckle off the pull back rims. That way you have a nice new pin, unmarred by pliers, and you end up with an extra set of pins, in case you bend your other ones pulling them out.\r\n\r\nI also save the screw that holds the pullbacks together, it\'s the same as the one that holds the bulkhead down on the Microsizer.');
