INSERT INTO phpbb_posts_text VALUES (24170, 'b08fca92b2', '', 'if you want you can change the frequency entirely with this mod my brothers 49mhz microsizer wasnt responding to its controler so i changed it to a 45mhz and used a shen controler from one of his other cars\r\n\r\nnow it gets 15-20ft range');
