INSERT INTO phpbb_posts_text VALUES (24402, '81f06dde4b', '', 'Holy Moly, I won.\r\n\r\nHave to give thanks to All the Bit Pimps for inspiring me to do my best on my cars. To Cabo for Having this great site. To All the other entrants who put their great cars in this contest.\r\n\r\nTo tell you the truth I didn\'t really think I was going to win.\r\n\r\nI had to read it several times to believe it.');
