INSERT INTO phpbb_posts_text VALUES (26538, 'b8681efd2c', '', 'So are you masking now dude or still hand painting?   \'Cuase those lines are lookin\' a lot sharper than previous jobs, I\'m enjoying your metamorphasis from your "technicolour S2000" days.....\r\n\r\nph2t.');
