INSERT INTO phpbb_posts_text VALUES (26546, '86ae8e8288', '', 'just another fine job by cabowabo...\r\n\r\nOk, now just stop...\r\n\r\nnice color combo...  Gold can come out nice...as you have done.\r\nMine always globs up on me.\r\n\r\nare those rented shoes?\r\n\r\nand now...what about the rest of the cars in the set?\r\n\r\n-nox');
