INSERT INTO phpbb_posts_text VALUES (27135, '5f27fb5bf7', '', 'Thank you!\r\n\r\nWe in germany have another Minicarproducer called "Minispeeder"!\r\nThey make a Chevybody(totally Boring)!\r\n\r\nI have done:\r\n\r\n-I have cut it to a Cabrio\r\n-I have built a new Front/a new End with Clay(Modelclay)\r\n-I have lowered the body\r\n-I have done  a new Paintjob in jellow\r\n-I have make some Decals with my PC\r\n-I have paint the window\r\n\r\nCarinlet:\r\n-I have cut some plastic\r\n-I have make the Carinlet with ModelClay\r\n-I have paint it with Red Color(Spraycan)\r\n\r\ni use Sandpaper for better results!');
