INSERT INTO phpbb_posts_text VALUES (27811, 'bb981ee719', '', 'welcome to da hood grunge.\r\n\r\nmost parts are interchangeable.\r\n- motors\r\n- batteries\r\n- wheels / tires\r\n- bodies\r\n\r\nsome are as easy as just popping it in place, others require more modifications to make them fit correctly.\r\n\r\nbits, microsizers, and some clones fit less with zipzaps than with their own versions, and vice versa');
