INSERT INTO phpbb_posts_text VALUES (29249, '36d27fde6d', '', 'The LXX boosters like the new beetles RULE. They steering is as good if not better than a real BCG.\r\n\r\nAs for Shen\'s there my fave car. Over all wicked performance with great steering and good speed/torque stock');
