INSERT INTO phpbb_posts_text VALUES (29944, '68de83154a', '', '[b:68de83154a]Entry:[/b:68de83154a] #5\r\n[b:68de83154a]Contestant:[/b:68de83154a] dabigpig\r\n[b:68de83154a]Stats:[/b:68de83154a]\r\n- paint \r\n- wheels off a micro machines monster truck \r\n- body lift \r\n- led fog\'s \r\n- staple intercooler \r\n- 2.6 kit motor\r\n[img:68de83154a]http://bitpimps.lixlink.com/pages/phpGallery/albums/userpics/10001/contests/2003_blowout/dabigpig_2_1.jpg[/img:68de83154a]');
INSERT INTO phpbb_posts_text VALUES (29945, '009708ac58', '', '[b:009708ac58]Entry:[/b:009708ac58] #6\r\n[b:009708ac58]Contestant:[/b:009708ac58] midget_man1387\r\n[b:009708ac58]Stats:[/b:009708ac58]\r\n- pretty much completely custom mitsu eclipse ZZ \r\n- body kit-made from gameboy cases \r\n- paint-silver fade to green \r\n- rims-dub city \r\n- internal dual cell \r\n- different interior than normal ZZ, includes single seat, NOS bottle, steering wheel and extra piece for convy roof \r\n- "cabo tailights" \r\n- pentip exhaust that goes into the body \r\n- "PIMPN IT" liscense plate\r\n[img:009708ac58]http://bitpimps.lixlink.com/pages/phpGallery/albums/userpics/10001/contests/2003_blowout/midgetman_1_1.jpg[/img:009708ac58]\r\n[img:009708ac58]http://bitpimps.lixlink.com/pages/phpGallery/albums/userpics/10001/contests/2003_blowout/midgetman_1_2.jpg[/img:009708ac58]');
