INSERT INTO phpbb_posts_text VALUES (29948, '90384fa5f3', '', 'I do think MA makes a good point: if we judged Bits by, say, a stock MS Sport out of the box with a 1.6 motor and medium tires all around, we wouldn\'t think it was that great either.');
INSERT INTO phpbb_posts_text VALUES (29949, '82bcc5dfd9', '', '[b:82bcc5dfd9]Entry:[/b:82bcc5dfd9] #8\r\n[b:82bcc5dfd9]Contestant:[/b:82bcc5dfd9] bdebde\r\n[b:82bcc5dfd9]Stats:[/b:82bcc5dfd9]\r\n- 35th anniversary Camaro on standard Zip Zap chassis \r\n- T-tops \r\n- Interior \r\n- Lowered tabs \r\n- Small bit wheels \r\n- Clone tires \r\n- Mosfets \r\n- Purple Zip Zap 3.4 motor \r\n- Red 8.25:1 gears\r\n[img:82bcc5dfd9]http://bitpimps.lixlink.com/pages/phpGallery/albums/userpics/10001/contests/2003_blowout/bdebde_1_1.jpg[/img:82bcc5dfd9]\r\n[img:82bcc5dfd9]http://bitpimps.lixlink.com/pages/phpGallery/albums/userpics/10001/contests/2003_blowout/bdebde_1_2.jpg[/img:82bcc5dfd9]');
INSERT INTO phpbb_posts_text VALUES (29950, 'ded45c0910', '', '[b:ded45c0910]Entry:[/b:ded45c0910] #9\r\n[b:ded45c0910]Contestant:[/b:ded45c0910] BilboBaggins\r\n[b:ded45c0910]Stats:[/b:ded45c0910]\r\n- Zip Zap Mustang, shortened to fit BCG and converted to convertible. \r\n- Precious\r\n- Tab Lowered front\r\n- exhaust tip attached to chassis.\r\n- Wheels Painted Gold to match paint scheme.\r\n- Blue Cat5 antenna.\r\n[img:ded45c0910]http://bitpimps.lixlink.com/pages/phpGallery/albums/userpics/10001/contests/2003_blowout/bilbobaggins_1_1.jpg[/img:ded45c0910]\r\n[img:ded45c0910]http://bitpimps.lixlink.com/pages/phpGallery/albums/userpics/10001/contests/2003_blowout/bilbobaggins_1_2.jpg[/img:ded45c0910]');
