INSERT INTO phpbb_posts_text VALUES (29952, '53a0488787', '', '[b:53a0488787]Entry:[/b:53a0488787] #11\r\n[b:53a0488787]Contestant:[/b:53a0488787] bdebde\r\n[b:53a0488787]Stats:[/b:53a0488787]\r\n- Old Honda Civic body on Zip Zap SE chassis \r\n- Custom paint, purple with yellow fade \r\n- Extra dark window tint (pimp style) \r\n- 1/8th inch drop, (no room for lights) \r\n- Nakamichi wheels with purple tires \r\n- Purple 3.4 motor (of course) \r\n- Green 9.86:1 gears \r\n- Mosfet mod soon to come\r\n[img:53a0488787]http://bitpimps.lixlink.com/pages/phpGallery/albums/userpics/10001/contests/2003_blowout/bdebde_2_1.jpg[/img:53a0488787]\r\n[img:53a0488787]http://bitpimps.lixlink.com/pages/phpGallery/albums/userpics/10001/contests/2003_blowout/bdebde_2_2.jpg[/img:53a0488787]');
