INSERT INTO phpbb_posts_text VALUES (30540, 'ccd67d9b86', 'Ahh5hit\'s Customized Skyline', 'My first custom paint job on an Xmod...\r\n\r\nI painted the yellow Skyline with Tamiya Gunmetal.\r\n\r\nFully upgraded, extra\'s include aluminum wheel locknuts, extra running lights, custom made aluminum skid plate, and I lowered the "Wild" spoiler.\r\n\r\n[img:ccd67d9b86]http://www.rcpics.net/media/SE_105.jpg[/img:ccd67d9b86]\r\n[img:ccd67d9b86]http://www.rcpics.net/media/SE_106.jpg[/img:ccd67d9b86]\r\n[img:ccd67d9b86]http://www.rcpics.net/media/SE_107.jpg[/img:ccd67d9b86]\r\n[img:ccd67d9b86]http://www.rcpics.net/media/SE_109.jpg[/img:ccd67d9b86]\r\n[img:ccd67d9b86]http://www.rcpics.net/media/SE_102.jpg[/img:ccd67d9b86]');
