INSERT INTO phpbb_posts_text VALUES (30674, '9c0f23b762', '', 'Hey nox, here\'s the circuit I\'ve come up with.  The lefthand side is your basic two transistor LED flasher.  Instead of the LEDs going straight to the positive voltage rail, they are fed from the 555 timer circuit which gives them that strobe effect (basically a square wave generator).\r\n\r\n[img:9c0f23b762]http://www.prahranpianos.com/bit_g/cop_lights_proto1.JPG[/img:9c0f23b762]');
