INSERT INTO phpbb_posts_text VALUES (32147, '52e1934ca2', '', 'Here\'s a couple of things to check:\r\n\r\n- If you\'re using an AMD setup, you got the latest VIA drivers?\r\n- Any IRQ conflicts?\r\n- Latest Win2k Service Pack?\r\n- Properly setup ASPI drivers for Win2k?\r\n- Check your jumpers, is the drive set properly for Slave or Master?\r\n\r\nGood luck.');
INSERT INTO phpbb_posts_text VALUES (32148, 'ab760971ff', 'The Dub Shop', 'Here\'s mine. For a while there, I wasn\'t sure if I was going to be able to do this stuff anymore. I\'m glad I stuck with it.\r\n\r\n[img:ab760971ff]http://www.digitalpose.com/mbr/1/32188/p/581174_1700307240442365003_vl.jpg[/img:ab760971ff]\r\n\r\nhere\'s an updated pic, with a custom sign. gotta represent....\r\n[img:ab760971ff]http://img.villagephotos.com/p/2003-11/492619/Bitpimpgarage.jpg[/img:ab760971ff]');
