INSERT INTO phpbb_posts_text VALUES (32249, '519895d35b', '', 'Ok. How about this? My third entry.....\r\n\r\nSpecs:\r\nTrue Blue pearl\r\nopening hood\r\nsingle windsheild wiper\r\nfully detailed motor\r\nchrome exhaust\r\ncustom front spoiler\r\nDub City rims\r\nmatching remote\r\nfully detailed body\r\n\r\n[img:519895d35b]http://www.digitalpose.com/mbr/1/32188/p/584415_3319524001355351213_vl.jpg[/img:519895d35b]\r\n[img:519895d35b]http://www.digitalpose.com/mbr/1/32188/p/586193_9159518312712595146_vl.jpg[/img:519895d35b]\r\n[img:519895d35b]http://www.digitalpose.com/mbr/1/32188/p/584430_6683391320541230978_vl.jpg[/img:519895d35b]\r\n\r\n\r\n[size=18:519895d35b]DubShop customs[/size:519895d35b]\r\n[url]http://www.geocities.com/lordhelmetr34/Dubshopcustoms.html?1070326748457[/url]');
