INSERT INTO phpbb_posts_text VALUES (34055, 'e7dad2658a', '', 'did u keep the charging part on the char-g?\r\nif so, heres a tut 4 ya!\r\n\r\nitems needed:\r\nfoil\r\nelectrical tape\r\nextra char-g chassis\r\nchar-g charger\r\nscissors\r\n\r\nwhat u do:\r\ncut 2 pieces of foil that can fit in the holes that the metal tabs from the \r\ncharger used to come thru.\r\nthread the foil in those 2 holes.\r\nnow get the other ends and put electrical tape on them so that they will not move,\r\nand tape that 2 the charging base on the char-g.\r\nleave it for 45 seconds and you are done!!!');
