INSERT INTO phpbb_posts_text VALUES (34502, 'e38568ad23', '', 'yup, sounds like a short somewhere.\r\nmake sure wires are connected well.\r\nmake sure wires aren\'t crossing over and tangling with other wires.\r\nmake sure your battery is seated properly.\r\nmake sure your pcb isn\'t smashing the wires and battery below.\r\nmake sure your pcb has a little room to play, it doesn\'t like tight situations.');
INSERT INTO phpbb_posts_text VALUES (34503, 'd04b67ec69', '', 'try wet sanding it down until its smoove.\r\nuse super fine grit wet sanding paper.\r\n\r\nit might dull the paint a tad, but you can put a nice thin coat over it when you\'re done or just clear coat it.\r\n\r\ngood luck');
