INSERT INTO phpbb_posts_text VALUES (48439, 'd9f786ee26', 'New fully Prop 1/45 Epoch Clone', 'The car is called a DG Master made by Think Happy. they are 1/45 scale same size as the Epoch. They have buttons on the controller for the hazards, blinkers, and headlights.  \r\n\r\nhttp://www.nipponhobbies.com/radio/DG_Master.htm\r\n\r\nThe Jap Commerical for these cars are here:\r\n\r\nhttp://www.ccp-jp.com/newtoy/products/dgmaster/movie/DG_Master_256.wmv');
