INSERT INTO phpbb_posts_text VALUES (34778, '227a320c32', 'Skyline Thunder', 'Hi! \r\n\r\nThis is my entry: \r\n\r\nSkyline clone body and a lot of work with epoxy putty, sandpaper, dremel etc. \r\nOn a 27mhz Microsizers Booster \r\nheadlights and rearlights made of plexiglass and led \r\nmetal grill \r\nquad metal exhaust \r\ndouble string antenna \r\npainted alloy rims \r\ncustom made spring suspension \r\n\r\n[img:227a320c32]http://www.gdynia.mm.pl/~miva//mrc/bp/Photo0.jpg[/img:227a320c32]\r\n\r\n[img:227a320c32]http://www.gdynia.mm.pl/~miva//mrc/bp/Photo1.jpg[/img:227a320c32]\r\n\r\n[img:227a320c32]http://www.gdynia.mm.pl/~miva//mrc/bp/Photo2.jpg[/img:227a320c32]\r\n\r\nName is Thunder because there will be thunder painting on the body');
