INSERT INTO phpbb_posts_text VALUES (35842, 'ab2ce1402f', '', 'Heres Some shots of it ouside. It was kind of a cloudy yucky day out.\r\n\r\nThis pic is of ducks 75 Ft away using 8x optical zoom no flash. Remeber to always click the accualy size button in bottom corner of IE. This will give you a real look at the raw image.\r\n\r\nhttp://members.rogers.com/forbitpimps/images/75Ft%20away%20using%208X%20optical%20Zoom.JPG\r\n\r\nThis is a close up of a duck. I was 3-5Ft away no zoom/flash.\r\n\r\nhttp://members.rogers.com/forbitpimps/images/Ducks%20Close%20Up%2003.JPG');
INSERT INTO phpbb_posts_text VALUES (35843, '11df6c644a', 'Zip Zap inductors', 'How can I get some inductors for my Radio Shack Zip Zap? On the cars PCB at position L4 is a inductor with "CEC 101k" printed on it. Does anyone know of where I can obtain some replacements?');
