INSERT INTO phpbb_posts_text VALUES (35908, '93806a616d', 'DVD Shrink', 'You can\'t beat FREE man!\r\n\r\nDVD Shrink 3.1.3 is the current version. from here:\r\n[url]http://www.mrbass.org/dvdshrink/[/url]\r\n\r\nWhat is DVD Shrink you ask? Simple...Put the DVD movie (like from Blockbuster or Netflix) you want to \'backup\' in your DVD burner, crank up DVD Shrink and it\'ll do it\'s magic and compress the movie you want down to the standar DVD blank size that currently on the market (4.7gb).\r\n\r\nVERY sexy.');
