INSERT INTO phpbb_posts_text VALUES (36059, '3c74b01aef', '', 'Some motors don\'t come with the gear already assembled onto the motor shaft. The controller is designed to help you with this, when the gear is placed in the hole it will hold it steady for you while you slide in the shaft. It also spaces the gear at the correct length too.');
