INSERT INTO phpbb_posts_text VALUES (36183, '6c7087e412', '', 'yea sounds like the battery in your car isn\'t getting enough charge.\r\n\r\nif you\'ve soldered correctly in your controller, all you\'re doing is adding 2 extra wires to jump straight from the battery posts in your controller to the charging stand on your controller.\r\n\r\nif done right, now your controller has no "timer" when charging - so you need to charge longer.\r\n\r\ndon\'t overcharge your battery though or you\'ll fry it.');
