INSERT INTO phpbb_posts_text VALUES (42608, '8b7ec477b5', '', 'Pullbacks are the end all be all of tires in the bit world...\r\n\r\nIf the fronts are too grippy for you hue, just change up your compound by using a bit of baby powder on the fronts.    You coat em enough, and they\'ll slide like hard plastic.\r\n\r\n\r\n\r\n\r\nsilla :D');
