INSERT INTO phpbb_posts_text VALUES (43140, '3641a6c1b4', '', 'Thanks, Pimps!!!  I have a Bb in the works now, its a truck conversion.  Got a lot of work to do there yet.\r\n\r\nI wanted to add that all the painting was freehand, no masking.\r\n\r\nHeres a couple more pics.  I hope these are better.\r\n\r\n\r\n[img:3641a6c1b4]http://img28.photobucket.com/albums/v85/sg219/RC%20Pimp%20Stuff/Project%20SG/prolectsgV2_012.jpg[/img:3641a6c1b4]\r\n\r\n[img:3641a6c1b4]http://img28.photobucket.com/albums/v85/sg219/RC%20Pimp%20Stuff/Project%20SG/prolectsgV2_013.jpg[/img:3641a6c1b4]');
