INSERT INTO phpbb_posts_text VALUES (43488, 'bcbe3c7e0a', '', 'Hond-issan Accordia\r\nchopped Honda Accord and chopped Nissan Gloria. I\'m using the front of the Honda and the rear of the Gloria.\r\n[img:bcbe3c7e0a]http://bitpimps.lixlink.com/pages/phpGallery/albums/userpics/10008/hondissan_accordia_1.jpg[/img:bcbe3c7e0a]\r\n[img:bcbe3c7e0a]http://bitpimps.lixlink.com/pages/phpGallery/albums/userpics/10008/hondissan_accordia_2.jpg[/img:bcbe3c7e0a]\r\n[img:bcbe3c7e0a]http://bitpimps.lixlink.com/pages/phpGallery/albums/userpics/10008/hondissan_accordia_3.jpg[/img:bcbe3c7e0a]\r\n[img:bcbe3c7e0a]http://bitpimps.lixlink.com/pages/phpGallery/albums/userpics/10008/hondissan_accordia_4.jpg[/img:bcbe3c7e0a]');
