INSERT INTO phpbb_posts_text VALUES (45361, 'a6efd95798', '', 'Yeah..... that\'s real.\r\n\r\nIt\'s worth it for the quick charge in my case though... I use my set for 2 rides, and it cuts down on the hassles(45 minutes is a hassle lol).\r\n\r\nAnd the few extra mahs is worth it, too :-)');
