INSERT INTO phpbb_posts_text VALUES (46935, 'f5ad4fbca7', 'bitPimps Auction Block: Gallery', 'We\'ll be using this thread to post all the rides for you to bid from.\r\nThis should be considered a "gallery" of sorts (there for it is locked), to make it easy - we\'re creating another thread dedicated to "bids" only and another thread dedicated to "questions and comments" only.\r\nBoth the "Auction Block", "Bids", and "Questions and Comments" threads will be dedicated purely to the auctions.\r\nFeel free to create a new post if you have a question or comment we haven\'t already addressed.\r\n\r\nword to bigbird :D');
