INSERT INTO phpbb_posts_text VALUES (48020, '208a903cb2', 'Initial-D ZZ SE\'s for 50% off', 'If you watch the Initial D DVDs you will find in disk 5 coupon for radioshack for a starter kit and upgrade kit together for 50% off.\r\n\r\n[img:208a903cb2]http://pic8.picturetrail.com/VOL248/1115503/2412489/57735161.jpg[/img:208a903cb2]\r\n\r\n[img:208a903cb2]http://pic8.picturetrail.com/VOL248/1115503/2412489/57735184.jpg[/img:208a903cb2]\r\n\r\nTHE DVD\r\n[img:208a903cb2]http://pic8.picturetrail.com/VOL248/1115503/2412489/57773019.jpg[/img:208a903cb2]');
