INSERT INTO phpbb_posts_text VALUES (49914, '7cd3d1f70c', 'Team Cars / flame airbrushing', 'Hey ya\'ll and yehaw,\r\nHope everyone is doin ok.\r\nHeres a look at my latest airbrush work on the tenth scales,\r\nThe blue one is my NTC3, the other three are my teammates R40\'s.\r\nDesigned and drawn on frisket paper, cut out with an exacto, and the paint masks stuck onto the body.  \r\nI hope to try some liquid mask on later projects.\r\nI came in 2nd today and won $12!\r\n\r\nFlames are fun.........\r\n[img:7cd3d1f70c]http://members.cox.net/silentwolv/Paint4.jpg[/img:7cd3d1f70c]');
